"use client";

import "./card.css";

import type React from "react";

import { cn } from "tailwind-variants";

import { CardContext, useCardContext } from "./card.context";
import { cardVariants, type CardVariants } from "./card.variants";

export type CardProps = CardVariants & React.ComponentProps<"div">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardRoot = ({ children, className, variant, ...props }: CardProps) => {
  const slots = cardVariants({ variant });

  return (
    <CardContext.Provider value={{ slots }}>
      <div className={cn(slots.root(), className)} {...props}>
        {children}
      </div>
    </CardContext.Provider>
  );
};

export type CardHeaderProps = React.ComponentProps<"div">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardHeader = ({ className, ...props }: CardHeaderProps) => {
  const { slots } = useCardContext();
  return <div className={cn(slots.header(), className)} {...props} />;
};

export type CardTitleProps = React.ComponentProps<"h3">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardTitle = ({ className, ...props }: CardTitleProps) => {
  const { slots } = useCardContext();
  return <h3 className={cn(slots.title(), className)} {...props} />;
};

export type CardDescriptionProps = React.ComponentProps<"p">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardDescription = ({ className, ...props }: CardDescriptionProps) => {
  const { slots } = useCardContext();
  return <p className={cn(slots.description(), className)} {...props} />;
};

export type CardContentProps = React.ComponentProps<"div">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardContent = ({ className, ...props }: CardContentProps) => {
  const { slots } = useCardContext();
  return <div className={cn(slots.content(), className)} {...props} />;
};

export type CardFooterProps = React.ComponentProps<"div">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const CardFooter = ({ className, ...props }: CardFooterProps) => {
  const { slots } = useCardContext();
  return <div className={cn(slots.footer(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const cardVariants = tv({
  slots: {
    root: "card",
    header: "card__header",
    title: "card__title",
    description: "card__description",
    content: "card__content",
    footer: "card__footer",
  },
  variants: {
    variant: {
      default: { root: "card--default" },
      outline: { root: "card--outline" },
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export type CardVariants = VariantProps<typeof cardVariants>;

"use client";

import { createContext, useContext } from "react";

import { cardVariants } from "./card.variants";

export type CardContext = {
  slots: ReturnType<typeof cardVariants>;
};

export const CardContext = createContext<CardContext | null>(null);

export const useCardContext = () => {
  const context = useContext(CardContext);
  return context ?? { slots: cardVariants() };
};

.card {
  @apply bg-card text-card-foreground rounded-xl border;
}

.card--default {
  @apply shadow-sm;
}

.card--outline {
  @apply shadow-none;
}

.card__header {
  @apply flex flex-col gap-1.5 p-6;
}

.card__title {
  @apply text-lg leading-none font-semibold tracking-tight;
}

.card__description {
  @apply text-muted-foreground text-sm;
}

.card__content {
  @apply p-6 pt-0;
}

.card__footer {
  @apply flex items-center p-6 pt-0;
}

import { CardContent, CardDescription, CardFooter, CardHeader, CardRoot, CardTitle } from "./card";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/card/content.md
 */
export const Card = {
  Content: CardContent,
  Description: CardDescription,
  Footer: CardFooter,
  Header: CardHeader,
  Root: CardRoot,
  Title: CardTitle,
};

export { CardContent, CardDescription, CardFooter, CardHeader, CardRoot, CardTitle };

export type {
  CardContentProps,
  CardDescriptionProps,
  CardFooterProps,
  CardHeaderProps,
  CardProps,
  CardTitleProps,
} from "./card";

export { CardContext, useCardContext } from "./card.context";
export { type CardVariants, cardVariants } from "./card.variants";
